SELECT * FROM (SELECT MIN(Description) AS Description, ErrNumber, MIN(LinkPart) AS LinkPart, MIN(Startstamp) AS Started, SEC_TO_TIME(SUM(TIMESTAMPDIFF(SECOND, StartStamp, StopStamp))) AS Duration, COUNT(*) AS Count, CASE MAX(Severity) WHEN 0 THEN 'INVALID' WHEN 1 THEN 'INFORMATION ONLY' WHEN 2 THEN 'GOOD MSG' WHEN 3 THEN 'WARNING' WHEN 4 THEN 'FULL WARNING' WHEN 5 THEN 'ERROR SYSTEM STILL RUNNING' WHEN 6 THEN 'HARD ERROR  SYSTEM STOPS' WHEN 7 THEN 'JAM ERROR  SYSTEM STOPS' WHEN 8 THEN 'FULLJAM' ELSE 'UNKNOWN' END AS Severity FROM Error_Log GROUP BY ErrNumber) AS ErrorAnalysis ORDER BY Started DESC
